DROP POLICY "Sale items read" ON public.sale_items;
DROP POLICY "Sale items write" ON public.sale_items;
CREATE POLICY "Sale items read" ON public.sale_items FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM sales s WHERE s.id=sale_id AND public.can_access_branch(s.pharmacy_id,s.branch_id)));
CREATE POLICY "Sale items write" ON public.sale_items FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM sales s WHERE s.id=sale_id AND public.can_access_branch(s.pharmacy_id,s.branch_id) AND public.can_write_pharmacy(s.pharmacy_id,ARRAY['manager','pharmacist','cashier']::user_role[]))) WITH CHECK(EXISTS(SELECT 1 FROM sales s WHERE s.id=sale_id AND public.can_access_branch(s.pharmacy_id,s.branch_id) AND public.can_write_pharmacy(s.pharmacy_id,ARRAY['manager','pharmacist','cashier']::user_role[])));
DROP POLICY "Sale payments read" ON public.sale_payments;
DROP POLICY "Sale payments write" ON public.sale_payments;
CREATE POLICY "Sale payments read" ON public.sale_payments FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM sales s WHERE s.id=sale_id AND public.can_access_branch(s.pharmacy_id,s.branch_id)));
CREATE POLICY "Sale payments write" ON public.sale_payments FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM sales s WHERE s.id=sale_id AND public.can_access_branch(s.pharmacy_id,s.branch_id) AND public.can_write_pharmacy(s.pharmacy_id,ARRAY['manager','pharmacist','cashier']::user_role[]))) WITH CHECK(EXISTS(SELECT 1 FROM sales s WHERE s.id=sale_id AND public.can_access_branch(s.pharmacy_id,s.branch_id) AND public.can_write_pharmacy(s.pharmacy_id,ARRAY['manager','pharmacist','cashier']::user_role[])));
DROP POLICY "Stock movement read" ON public.stock_movements;
DROP POLICY "Stock movement write" ON public.stock_movements;
CREATE POLICY "Stock movement read" ON public.stock_movements FOR SELECT TO authenticated USING(public.is_platform_admin() OR public.is_pharmacy_owner(pharmacy_id) OR EXISTS(SELECT 1 FROM inventory_batches b WHERE b.id=batch_id AND public.can_access_branch(b.pharmacy_id,b.branch_id)));
CREATE POLICY "Stock movement write" ON public.stock_movements FOR ALL TO authenticated USING(public.can_write_pharmacy(pharmacy_id,ARRAY['manager','inventory_manager','pharmacist']::user_role[]) AND (public.is_platform_admin() OR public.is_pharmacy_owner(pharmacy_id) OR EXISTS(SELECT 1 FROM inventory_batches b WHERE b.id=batch_id AND public.can_access_branch(b.pharmacy_id,b.branch_id)))) WITH CHECK(public.can_write_pharmacy(pharmacy_id,ARRAY['manager','inventory_manager','pharmacist']::user_role[]) AND (public.is_platform_admin() OR public.is_pharmacy_owner(pharmacy_id) OR EXISTS(SELECT 1 FROM inventory_batches b WHERE b.id=batch_id AND b.pharmacy_id=stock_movements.pharmacy_id AND public.can_access_branch(b.pharmacy_id,b.branch_id))));